import csv,json,sys
from pathlib import Path
totals={}
with open(sys.argv[1],newline='',encoding='utf-8') as stream:
    for row in csv.DictReader(stream):
        account=row['account']
        totals[account] = totals.get(account, 0) + int(row['delta'])
result={'balances':[{'account':key,'balance':totals[key]} for key in sorted(totals)]}
print(json.dumps(result,ensure_ascii=False))

